CustomField.formula:
/*First if completed same day*/
if( DateValue(Latest_Client_Sent__c)=TODAY(), 
/*Adjusts Closed Hour/Minute if it's before or after hours*/
	if(Current_Work_Hour__c<8, 8, if(Current_Work_Hour__c>20, 20, Current_Work_Hour__c))+
	if(Current_Work_Hour__c<8 || Current_Work_Hour__c>20, 0, Minute(TimeValue(NOW()))/60)
	- 
/*Adjust Created Hour/Minute if it's before or after hours*/
	(if(Latest_Client_Sent_Hour__c<8, 8, if(Latest_Client_Sent_Hour__c>20, 20, Latest_Client_Sent_Hour__c))+
	if(Latest_Client_Sent_Hour__c<8 || Latest_Client_Sent_Hour__c>20 ,0, Minute(TimeValue(Latest_Client_Sent__c)))/60),



/*If not the same day, calcs hours of first day, if after hours or weekend rounds Created down and Completed up*/
	if( Weekday(DateValue(Latest_Client_Sent__c))=7 || Weekday(DateValue(Latest_Client_Sent__c))=0 ||  Latest_Client_Sent_Hour__c>=20, 0, 
/*If it's before hours, limit to 8 hours*/
	if(Latest_Client_Sent_Hour__c<8, 8, 20-(Latest_Client_Sent_Hour__c))+
	if(Latest_Client_Sent_Hour__c<8 || Latest_Client_Sent_Hour__c>20, 0, (Minute(TimeValue(Latest_Client_Sent__c))/60))
    )
    +
/*Calcs days between and converts to hours by multiplying by 8 workhours*/
	(CASE( WEEKDAY(DateValue(Latest_Client_Sent__c)),
/*This excludes End Dates e.g. Mon Tuesday Wednesday = 1*/
1 , CASE( MOD( Today()-DateValue(Latest_Client_Sent__c),7),1,0,2,1,3,2,4,3,5,4,6,5,0),
2 , CASE( MOD( Today()-DateValue(Latest_Client_Sent__c),7),1,0,2,1,3,2,4,3,5,3,6,3,0),
3 , CASE( MOD( Today()-DateValue(Latest_Client_Sent__c),7),1,0,2,1,3,2,4,2,5,2,6,3,0),
4 , CASE( MOD( Today()-DateValue(Latest_Client_Sent__c),7),1,0,2,1,3,1,4,1,5,2,6,3,0),
5 , CASE( MOD( Today()-DateValue(Latest_Client_Sent__c),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
6 , CASE( MOD( Today()-DateValue(Latest_Client_Sent__c),7),1,0,2,0,3,0,4,1,5,2,6,3,0),
7 , CASE( MOD( Today()-DateValue(Latest_Client_Sent__c),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
999)
+
(FLOOR(( Today()-DateValue(Latest_Client_Sent__c) )/7)*5))*8
	+
/*Calcs days at the end*/
/*If it's before hours, limit to 8 hours*/
	if(Current_Work_Hour__c<8, 0, if(Current_Work_Hour__c>20, 20, Current_Work_Hour__c-8))+
	if(Current_Work_Hour__c<8 || Current_Work_Hour__c>20, 0, (Minute(TimeValue(NOW()))/60))

)
